import{_ as t,l as i,o as a,c,v as o,p as s,x as r,d as n,i as E,S as l}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"子查询去相关","description":"","frontmatter":{"title":"子查询去相关","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/subquery-decorrelation.md","filePath":"cs/subquery-decorrelation.md","lastUpdated":1789023840000}'),p={name:"cs/subquery-decorrelation.md"};function h(B,e,u,A,_,m){const d=i("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="子查询去相关" tabindex="-1">子查询去相关 <a class="header-anchor" href="#子查询去相关" aria-label="Permalink to &quot;子查询去相关&quot;">​</a></h1><div class="epigraph"><p>相关子查询按外层行一次次求值；去相关把它改成连接、半连接或聚合，指称不变，计划才能用连接算法。</p><footer>—— 据 Kim, On Optimizing an SQL-like Nested Query, TODS 1982；Seshadri et al. 对复杂子查询；Ramakrishnan and Gehrke 整理</footer></div><p><a href="/cs/window-functions">上一课</a>把邻居计算收进 <code>OVER</code>。本课不重讲帧。缺口是嵌套：<code>WHERE x IN (SELECT …)</code>、<code>EXISTS</code>、标量子查询，尤其外层列出现在内层时——朴素执行是嵌套循环，优化器看不见 <a href="/cs/join-algorithms">连接算法</a>。去相关（decorrelation）是改写，不是换一种 SQL 方言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/query-rewrite">查询改写</a> 已点名「相关子查询去相关，以便进入连接」。本课补机制。相关：内层查询的谓词引用外层元组。逐行求值语义清楚，代价是内层反复启动。不相关子查询可先物化一次；相关则必须对每个外层行换参数。</p><p>缺口是<strong>把嵌套演算改回代数</strong>：<code>IN</code>/<code>EXISTS</code> 变半连接；标量聚合子查询变分组再连接；<code>NOT EXISTS</code> 变反半连接。改写必须在包语义与 NULL 下保持指称：<code>IN</code> 遇 NULL 走三值，不是简单等值连接。</p><p><span class="marginnote">Kim 1982 给出嵌套查询的分类与变换。后来的论文处理 <code>COUNT</code> 陷阱：空内层 <code>COUNT</code> 为 0，内连接会丢掉外层行，需外连接补零。本课承认这类缝，不假装所有子查询都能无脑变 inner join。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先分类：不相关 / 相关；标量 / 存在 / 量化（<code>ALL</code>/<code>ANY</code>）；是否含聚合。不相关且无副作用：一次求值，结果当临时关系。相关存在：<code>R ⋉ S</code>（半连接），<code>S</code> 带外层参数改成连接条件。相关聚合：内层按相关列 <code>GROUP BY</code>，再与外层连接；空组用外连接与 <code>COALESCE</code>。</p><p>优化器也可以选择<strong>不去相关</strong>，用索引做相关嵌套循环——当内层有可用索引且外层小时，这比哈希连接更便宜。去相关是合法变换集合，不是强制。</p>',10)),(a(),s(l,null,{default:r(()=>[E(d,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NQ%5B%22%E5%B5%8C%E5%A5%97%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20COR%5B%22%E6%98%AF%E5%90%A6%E7%9B%B8%E5%85%B3%22%5D%0A%20%20COR%20--%3E%20ONCE%5B%22%E4%B8%8D%E7%9B%B8%E5%85%B3%3A%20%E6%B1%82%E5%80%BC%E4%B8%80%E6%AC%A1%22%5D%0A%20%20COR%20--%3E%20DEC%5B%22%E5%8E%BB%E7%9B%B8%E5%85%B3%3A%20%E8%BF%9E%E6%8E%A5%20%2F%20%E5%8D%8A%E8%BF%9E%E6%8E%A5%20%2F%20%E5%88%86%E7%BB%84%22%5D%0A%20%20DEC%20--%3E%20JOIN%5B%22%E5%90%8E%E8%AF%BE%E8%BF%9E%E6%8E%A5%E7%AE%97%E5%AD%90%22%5D%0A%20%20NQ%20--%3E%20IDX%5B%22%E6%88%96%E4%BF%9D%E7%95%99%E7%9B%B8%E5%85%B3%20NLJ%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>去相关之后，<a href="/cs/predicate-pushdown">谓词下推</a> 与连接顺序搜索才有树可动。窗口与分组仍是防火墙：内层若含窗口，变换更窄。标量子查询运行时应保证最多一行；去相关后用聚合或显式基数检查表达同一约束，违反则运行时错，不是「悄悄变包」。</p><p><code>EXISTS</code> 只关心非空，不关心投影列；半连接可以提前在内层停。这与后课 <a href="/cs/set-ops-exists">集合运算与 EXISTS</a> 的声明写法衔接：本课动的是计划形状，下一课把集合差、存在量化收成用户可写的算子对照。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每家优化器的「子查询拉平」规则表抄进来。有副作用的函数、易失表、相关更新语句，去相关可能改变求值次数——主干把它们标成防火墙。也不处理递归 CTE；那是下一课之后。</p><p>后课默认：嵌套查询有指称；执行可以是相关 NLJ 或去相关后的连接。谈到「子查询慢」，先问是否相关、是否可改成半连接，而不是先加索引碰运气。</p><p>COUNT 与空集、NULL 与 IN，是去相关必须逐条核对的缝，不是边角。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>去相关把嵌套改成连接或半连接，指称不变才合法。</li><li>空组与 <code>COUNT</code>、三值 <code>IN</code> 是变换陷阱。</li><li>保留相关 NLJ 有时更优；去相关不是教条。</li><li>出处：Kim 1982；Seshadri 等；Ramakrishnan and Gehrke。</li></ul>',9))])}const T=t(p,[["render",h]]);export{N as __pageData,T as default};
